namespace TriReviewBridge {
 public static class Json {
  public static JavaScriptSerializer Codec=new JavaScriptSerializer(){MaxJsonLength=64000000};
  public static Dictionary<string,object> Obj(object v){return v as Dictionary<string,object>??new Dictionary<string,object>();}
  public static object Get(object v,string k){var o=Obj(v);return o.ContainsKey(k)?o[k]:null;}
  public static string Str(object v,string k){var x=Get(v,k);return x==null?"":Convert.ToString(x);}
  public static bool Bool(object v,string k){var x=Get(v,k);return x!=null&&Convert.ToBoolean(x);}
  public static object[] Arr(object v){return v is IEnumerable&&!(v is string)?((IEnumerable)v).Cast<object>().ToArray():new object[0];}
  public static Dictionary<string,object> D(params object[] a){var d=new Dictionary<string,object>();for(int n=0;n<a.Length;n+=2)d[(string)a[n]]=a[n+1];return d;}
  public static string Show(object v){return Codec.Serialize(v);}
 }
 public class BridgeClient {
  string Base,Token;
  public BridgeClient(string config){var c=Json.Codec.DeserializeObject(File.ReadAllText(config,Encoding.UTF8));int port=Convert.ToInt32(Json.Get(c,"port"));if(port==0){var s=Json.Codec.DeserializeObject(File.ReadAllText(Path.Combine(Path.GetDirectoryName(config),"workbench-service.json")));port=Convert.ToInt32(Json.Get(s,"port"));}Base="http://127.0.0.1:"+port;Token=Json.Str(c,"token");Pending=new ClientPendingStore(config);}
  static string Friendly(string message){var map=new Dictionary<string,string>{{"hybrid_recent_worker_identity_report_required","原会话身份报告缺失或已过期，请先准备并等待原生核对。"},{"hybrid_deepseek_native_not_verified","DSH原生通道尚未验证，保持暂停，文字可排队。"},{"hybrid_completed_text_task_required","请选择已有完整结果的纯文字任务。"},{"hybrid_task_revision_changed","任务版本已变化，请刷新并确认当前结果。"},{"hybrid_task_artifact_changed","任务内容已变化，请刷新并确认当前结果。"},{"issue_verification_requires_pass_for_this_issue","验证必须明确通过、关联当前Issue，并引用本版材料文件。"},{"engineering_task_cancelled_suspended_or_expired","原任务已取消、暂停或过期，只保留历史查看。"},{"delivery_requires_review_round_for_current_material","当前材料尚未进入匹配的审查轮次，请先开启必要复核。"},{"review_reopen_requires_actual_source_byte_change","源文件字节没有变化；仅重新生成快照不能重开完整审查。"},{"platform_hourly_material_delivery_limit","文字与材料的共享每小时投递额度已用尽。"},{"engineering_not_enabled","工程材料仍为隔离预览，请打开D盘平台中的“打开工程材料预览”入口。"},{"legacy_real_project_engineering_access_forbidden","原项目档案保持冻结，本轮只使用独立虚构工程。"},{"source_root_not_authorized","此来源目录未获授权；本轮仅接受界面列出的虚构工程目录。"},{"source_changed_create_new_snapshot","源文件已变化，请先捕获新快照，再生成新版本。"},{"package_file_integrity_failure","材料文件校验失败，已停止读取和导出。"},{"explicit_workspace_recipients_required","请明确选择当前空间内的接收方。"},{"recipient_unbound_paused_or_real_locked","所选接收方未绑定、已暂停或真实通道未授权，请重新选择。"},{"archived_scope_read_only","已归档项目或空间只允许查看。"},{"legacy_history_read_only","原型历史处于冻结状态，不会恢复原会话投递。"},{"review_not_approved","事项尚未技术审议通过，不能记录后续授权。"},{"snapshot_change_requires_new_revision","审批对象已变化，请提交新版本重新审查。"},{"budget_prevents_complete_chat_queue","额度不足，未向任何接收方排队。"},{"budget_prevents_complete_review_queue","额度不足，未向部分审查者投递。"},{"real_adapters_not_authorized","真实会话尚未取得单独授权。"},{"real_adapter_hard_locked","当前仅允许模拟接入。"},{"explicit_parent_action_required","Agent主动动作缺少可核对的原事项。"},{"cross_project_forward_requires_explicit_user_action","跨项目转交需要用户明确确认。"}};return map.ContainsKey(message)?map[message]:message;}
  ClientPendingStore Pending;Dictionary<string,string> LastSendKeys=new Dictionary<string,string>();
  string LogicalScope(string project,string workspace){return project+"\n"+workspace;}
  public PendingClientSend PendingSend(string project,string workspace){return Pending.Peek(project,workspace);}
  public void FinishLogicalSend(string project,string workspace,string expectedKey=null){string scope=LogicalScope(project,workspace),key;if(expectedKey==null&&!LastSendKeys.TryGetValue(scope,out expectedKey))return;Pending.Consume(project,workspace,expectedKey);if(LastSendKeys.TryGetValue(scope,out key)&&key==expectedKey)LastSendKeys.Remove(scope);}
  public async Task<object> ReplayPending(string project,string workspace){var r=Pending.Peek(project,workspace);if(r==null)throw new InvalidOperationException("本会话没有待核对的客户端请求。");return await ReplayPending(r);}
  public Task<object> ReplayPending(PendingClientSend expected){if(expected==null)throw new InvalidOperationException("恢复请求缺少已确认身份。");return SendTracked(new PendingSendTicket(){Record=expected,IsNew=false});}
  object Cached(PendingClientSend r){var value=Json.Codec.DeserializeObject(r.ResponseJson);if(r.State=="REJECTED")return Json.D("status","CLIENT_REQUEST_REJECTED","summary","原API请求已被后台拒绝："+Friendly(Json.Str(value,"error")),"governance",Json.Get(value,"governance"));return value;}
  async Task<object> SendTracked(PendingSendTicket ticket){using(Pending.AcquireSendLease(ticket.Record)){var r=Pending.BeginAttempt(ticket.Record);LastSendKeys[LogicalScope(r.ProjectId,r.WorkspaceId)]=r.RequestKey;if(r.State!="PENDING")return Cached(r);try{string raw=await Request(r.Path,r.Payload,r.RequestKey);var value=Json.Codec.DeserializeObject(raw);Pending.RecordResponse(r,raw,false);return value;}catch(ApiCallFailure error){if(ticket.IsNew&&r.AttemptCount==1&&new[]{400,403,404,409,422,429}.Contains(error.StatusCode)&&!String.IsNullOrEmpty(error.ResponseJson)){var response=Json.Codec.DeserializeObject(error.ResponseJson);if(!String.IsNullOrEmpty(Json.Str(response,"error")))Pending.RecordResponse(r,error.ResponseJson,true);}throw;}}}
  public async Task<object> Call(string path,object body=null){string payload=body==null?null:Json.Show(body);if(body!=null&&ClientPendingStore.Tracks(path))return await SendTracked(Pending.Prepare(path,payload));return Json.Codec.DeserializeObject(await Request(path,payload,body==null?null:Guid.NewGuid().ToString("N")));}
  sealed class ApiCallFailure:InvalidOperationException {public int StatusCode;public string ResponseJson;public ApiCallFailure(string message):base(message){}}
  async Task<string> Request(string path,string payload,string key){using(var web=new WebClient()){web.Proxy=null;web.Encoding=Encoding.UTF8;web.Headers[HttpRequestHeader.Authorization]="Bearer "+Token;try{if(payload==null)return await web.DownloadStringTaskAsync(Base+path);web.Headers[HttpRequestHeader.ContentType]="application/json; charset=utf-8";web.Headers["Idempotency-Key"]=key;return await web.UploadStringTaskAsync(Base+path,"POST",payload);}catch(WebException e){string message=e.Message,raw=null;object governance=null;int code=0;if(e.Response!=null){var http=e.Response as HttpWebResponse;if(http!=null)code=(int)http.StatusCode;using(var sr=new StreamReader(e.Response.GetResponseStream())){var candidate=sr.ReadToEnd();try{var parsed=Json.Codec.DeserializeObject(candidate);message=Json.Str(parsed,"error");governance=Json.Get(parsed,"governance");raw=candidate;}catch{}}}var operation=new ApiCallFailure(Friendly(message)){StatusCode=code,ResponseJson=raw};if(governance!=null)operation.Data["governance"]=governance;throw operation;}}}
 }
