  async Task RunSelfTest(){var p=await Client.Call("/api/projects",Json.D("name","虚构WPF桌面自检"));string pid=Json.Str(p,"id");var ws=await Client.Call("/api/projects/"+pid+"/workspaces",Json.D("name","虚构原生界面","participants",new string[]{"hermes","deepseek","chatgpt"}));CurrentScope=new Scope(){ProjectId=pid,ProjectName="虚构WPF桌面自检",WorkspaceId=Json.Str(ws,"id"),WorkspaceName="虚构原生界面"};foreach(string role in new string[]{"hermes","deepseek","chatgpt"})await Post("bind-simulation","agentId",role,"title","虚构 "+Name(role));await Post("configure","paused",false,"recipients",new string[]{"hermes"});await RefreshNavigation();await Choose(CurrentScope);var originalScope=CurrentScope;Composer.Text="虚构第一空间草稿";var second=await Client.Call("/api/projects/"+pid+"/workspaces",Json.D("name","虚构独立接收方","participants",new string[]{"deepseek"}));var alternate=new Scope(){ProjectId=pid,ProjectName="虚构WPF桌面自检",WorkspaceId=Json.Str(second,"id"),WorkspaceName="虚构独立接收方"};await Choose(alternate);await Post("bind-simulation","agentId","deepseek","title","虚构独立DeepSeek");await Post("configure","recipients",new string[]{"deepseek"});ParticipantKey="";await RefreshWorkspace();if(!Chosen().SequenceEqual(new string[]{"deepseek"}))throw new Exception("Workspace receiver selection did not update");Composer.Text="虚构第二空间草稿";await Choose(originalScope);if(Composer.Text!="虚构第一空间草稿")throw new Exception("Draft crossed workspace boundary");await Choose(alternate);if(Composer.Text!="虚构第二空间草稿")throw new Exception("Second draft was lost");await Choose(originalScope);if(!Chosen().SequenceEqual(new string[]{"hermes"}))throw new Exception("Workspace receiver restoration failed");var probeFile=SelfTest+".second-window.json";var child=OpenWindow(probeFile,alternate);for(int k=0;k<100&&!File.Exists(probeFile);k++)await Task.Delay(100);if(!File.Exists(probeFile)||child.HasExited)throw new Exception("Concurrent native window failed to start");await KnowledgeDialog();await AttachKnowledge();if(AttachedKnowledge.Count!=1)throw new Exception("Native knowledge explicit selection failed");Composer.Text="虚构桌面算式：2加3等于5。仅文字，不关联任何真实项目。";var sendOnce=Send();var accidentalSecond=Send();await Task.WhenAll(sendOnce,accidentalSecond);for(int n=0;n<50;n++){await Task.Delay(300);await RefreshWorkspace();if(Json.Arr(Json.Get(State,"messages")).Any(m=>Json.Str(m,"author")=="hermes"))break;}if(Json.Arr(Json.Get(State,"items")).Count(i=>Json.Str(i,"scope")=="text_only_chat")!=1)throw new Exception("Double-click duplicated message");await NewTask("虚构任务：整理三种虚构颜色，只输出文字。");await WaitForState(data=>Json.Arr(Json.Get(data,"items")).Any(i=>Json.Str(i,"scope")=="text_only_task"&&Json.Str(i,"state")=="awaiting_user_acceptance"),"native text task");await NewReview("虚构审议：3加4等于7。只核对文字。",null);await WaitForState(data=>Json.Arr(Json.Get(data,"items")).Any(i=>Json.Str(i,"scope")=="text_only_review"&&Json.Str(i,"state")=="approved"),"native review");var review=Items.ItemsSource.Cast<ItemRow>().First(i=>i.TypeLabel=="正式审批");await NewReview(review.Body+"\n修订：明确仅审查虚构算式。",review);await WaitForState(data=>Json.Arr(Json.Get(data,"items")).Any(i=>Json.Str(i,"scope")=="text_only_review"&&Json.Str(i,"revision")=="2"&&Json.Str(i,"state")=="approved"),"native revised review");File.WriteAllText(probeFile+".release","close");for(int k=0;k<100&&!child.HasExited;k++)await Task.Delay(100);if(!child.HasExited||child.ExitCode!=0||!Json.Bool(Json.Codec.DeserializeObject(File.ReadAllText(probeFile)),"passed"))throw new Exception("Concurrent window isolation failed");MainTabs().SelectedIndex=0;bool received=Json.Arr(Json.Get(State,"messages")).Any(m=>Json.Str(m,"author")=="hermes");if(!received)throw new Exception("WPF simulated reply was not received");Win.UpdateLayout();await RunMaterialsSelfTest();await RunGovernanceSelfTest();await RunUxSelfTest();await RunCollaborationSelfTest();RunUxThemeSelfTest();await Task.Delay(150);Win.UpdateLayout();if(!String.IsNullOrEmpty(Export)){var bitmap=new RenderTargetBitmap((int)Win.ActualWidth,(int)Win.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(Win);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(Export))encoder.Save(output);}File.WriteAllText(SelfTest,Json.Show(Json.D("passed",true,"collaboration",CollabProof,"theme",UxThemeProof,"ux",UxProof,"engineeringMaterials",MaterialsProof,"governance",GovernanceProof,"draftStorage",DraftStore==null?null:DraftStore.FilePath,"draftProbeProject",pid,"draftProbeWorkspace",alternate.WorkspaceId,"windowType",Win.GetType().FullName,"webViewLoaded",AppDomain.CurrentDomain.GetAssemblies().Any(a=>a.FullName.Contains("WebView")),"messageCount",Messages.Items.Count,"simulatedReplyReceived",received,"workspaceReceiverRestore",true,"workspaceDraftIsolation",true,"inFlightDoubleSendGuard",true,"simultaneousNativeWindows",true,"isolatedSecondWindow",true,"knowledgeDialogAndExplicitAttachment",true,"taskDialogAndResult",true,"reviewDialogAndRevision",true,"projectId",pid,"workspaceId",CurrentScope.WorkspaceId,"realAdaptersAccessed",false,"closingWindowStopsBackend",false)),Encoding.UTF8);Win.Close();}

  Process OpenWindow(string probe,Scope target=null){if(target==null)target=CurrentScope;if(target==null||String.IsNullOrEmpty(target.WorkspaceId))throw new InvalidOperationException("请先选择会话窗口。");string args="--config \""+Config+"\" --project-id "+target.ProjectId+" --workspace-id "+target.WorkspaceId;args+=" --draft-profile ws-"+target.WorkspaceId;if(probe!=null)args+=" --window-probe \""+probe+"\"";return Process.Start(new ProcessStartInfo(){FileName=System.Reflection.Assembly.GetExecutingAssembly().Location,Arguments=args,UseShellExecute=false});}
  async Task ProbeWindow(){string id=CurrentScope.WorkspaceId;int count=Messages.Items.Count;File.WriteAllText(WindowProbe,Json.Show(Json.D("ready",true,"pid",Process.GetCurrentProcess().Id,"workspaceId",id)));for(int k=0;k<700&&!File.Exists(WindowProbe+".release");k++){await Task.Delay(100);await RefreshWorkspace();}bool passed=File.Exists(WindowProbe+".release")&&CurrentScope.WorkspaceId==id&&Messages.Items.Count==count&&Chosen().SequenceEqual(new string[]{"deepseek"});File.WriteAllText(WindowProbe,Json.Show(Json.D("passed",passed,"workspaceId",id,"messageCount",count,"separateProcess",true)));if(!passed)Environment.ExitCode=1;Win.Close();}
  async Task ProjectSettings(){if(CurrentScope==null)throw new InvalidOperationException("请选择项目。");var project=Navigation.First(x=>Json.Str(x,"id")==CurrentScope.ProjectId);var d=Dialog("项目说明与权限",680,650);var panel=new StackPanel(){Margin=new Thickness(18)};var description=Field(panel,"项目说明",Json.Str(project,"description"),3);panel.Children.Add(new TextBlock(){Text="本机用户保留所有权限。下方可登记其他主体的项目/当前会话权限；模拟Agent凭证仅通过受限测试接口发放，不操作真实Agent。",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,10,0,0)});var id=Field(panel,"主体ID（可留空，只保存说明）","",1);var name=Field(panel,"名称","",1);var permissions=Field(panel,"用户成员权限，逗号分隔","read,chat,task,review,knowledge:read",2);Accept(d,panel,"保存项目设置");d.Content=new ScrollViewer(){Content=panel};if(d.ShowDialog()==true){await Client.Call("/api/projects/"+CurrentScope.ProjectId+"/settings",Json.D("description",description.Text));if(!String.IsNullOrWhiteSpace(id.Text))await Client.Call("/api/projects/"+CurrentScope.ProjectId+"/members",Json.D("principalId",id.Text,"name",name.Text,"kind","user","permissions",permissions.Text.Split(',').Select(x=>x.Trim()).Where(x=>x.Length>0).ToArray(),"workspaceId",CurrentScope.WorkspaceId));await RefreshNavigation();await RefreshWorkspace();}}
  async Task KnowledgeDialog(){if(CurrentScope==null)throw new InvalidOperationException("请选择项目与会话。");await RefreshWorkspace();var d=Dialog("项目知识 · 默认不共享，不读取私有记忆",800,730);var p=new StackPanel(){Margin=new Thickness(18)};var knowledge=Json.Arr(Json.Get(State,"knowledge"));p.Children.Add(new TextBlock(){Text="选择已有卡片可创建新版本，或显式共享/撤销所选版本。内容只属于当前项目，不自动附加给Agent。",TextWrapping=TextWrapping.Wrap});var select=new ComboBox(){ItemsSource=(new string[]{"新卡片"}).Concat(knowledge.Select(k=>Json.Str(k,"title")+" · v"+Json.Str(k,"version")+(Json.Bool(k,"revoked")?" · 已撤销":""))).ToArray(),SelectedIndex=0,Margin=new Thickness(0,12,0,4)};p.Children.Add(select);var title=Field(p,"卡片标题","虚构项目事实",1);var body=Field(p,"正文（不得存私有记忆、凭证或真实凪材料）",String.IsNullOrEmpty(SelfTest)?"":"虚构知识：三种颜色为红、绿、蓝。",6);var kind=new ComboBox(){ItemsSource=new string[]{"fact","decision","research","task_material","document","meeting"},SelectedIndex=0};p.Children.Add(kind);select.SelectionChanged+=(sender,e)=>{if(select.SelectedIndex>0){var k=knowledge[select.SelectedIndex-1];title.Text=Json.Str(k,"title");body.Text=Json.Str(k,"body");kind.SelectedItem=Json.Str(k,"kind");}};var share=new CheckBox(){Content="明确共享本次保存版本给上方选中的接收方",IsChecked=!String.IsNullOrEmpty(SelfTest),Foreground=Brushes.White,Margin=new Thickness(0,12,0,4)};p.Children.Add(share);var revoke=new Button(){Content="撤销所选旧版本的共享",Margin=new Thickness(0,8,0,4)};revoke.Click+=async(sender,e)=>{try{if(select.SelectedIndex<1)throw new Exception("请选择版本。");var k=knowledge[select.SelectedIndex-1];await Client.Call("/api/projects/"+CurrentScope.ProjectId+"/knowledge-revoke",Json.D("cardId",Json.Str(k,"id"),"version",Convert.ToInt32(Json.Get(k,"version"))));d.Close();await RefreshWorkspace();}catch(Exception ex){MessageBox.Show(d,ex.Message);}};p.Children.Add(revoke);Accept(d,p,"保存为不可变新版本");d.Content=new ScrollViewer(){Content=p,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};if(d.ShowDialog()==true){object created;if(select.SelectedIndex==0)created=await Client.Call("/api/projects/"+CurrentScope.ProjectId+"/knowledge",Json.D("kind",kind.SelectedItem,"title",title.Text,"body",body.Text));else created=await Client.Call("/api/projects/"+CurrentScope.ProjectId+"/knowledge-version",Json.D("cardId",Json.Str(knowledge[select.SelectedIndex-1],"id"),"body",body.Text));if(share.IsChecked==true)await Client.Call("/api/projects/"+CurrentScope.ProjectId+"/knowledge-share",Json.D("cardId",Json.Str(created,"id"),"version",Convert.ToInt32(Json.Get(created,"version")),"recipients",Chosen()));await RefreshWorkspace();}}
  async Task AttachKnowledge(){await RefreshWorkspace();var d=Dialog("显式附加授权知识版本",700,520);var p=new StackPanel(){Margin=new Thickness(18)};p.Children.Add(new TextBlock(){Text="只附加已共享给全部当前接收方的版本；本次发送后清空选择。撤销共享将阻止后续投递。",TextWrapping=TextWrapping.Wrap});var boxes=new List<CheckBox>();foreach(var k in Json.Arr(Json.Get(State,"knowledge"))){if(Json.Bool(k,"revoked")||String.IsNullOrEmpty(Json.Str(k,"recipients")))continue;var allowed=Json.Arr(Json.Codec.DeserializeObject(Json.Str(k,"recipients"))).Select(Convert.ToString).ToArray();if(Chosen().Length==0||!Chosen().All(r=>allowed.Contains(r)))continue;var b=new CheckBox(){Content=Json.Str(k,"title")+" v"+Json.Str(k,"version"),Tag=k,IsChecked=!String.IsNullOrEmpty(SelfTest),Foreground=Brushes.White,Margin=new Thickness(4,10,4,4)};boxes.Add(b);p.Children.Add(b);}Accept(d,p,"仅对下一条消息或审批附加所选版本");d.Content=new ScrollViewer(){Content=p};if(d.ShowDialog()==true){AttachedKnowledge=boxes.Where(b=>b.IsChecked==true).Select(b=>{var k=b.Tag;return(object)Json.D("id",Json.Str(k,"id"),"version",Convert.ToInt32(Json.Get(k,"version")));}).ToList();Note("已为下一次发送选择 "+AttachedKnowledge.Count+" 个明确授权版本。");}}
  async Task ReviewRecord(){var i=SelectedItem();var d=Dialog("记录一致意见、分歧与未决问题",730,730);var p=new StackPanel(){Margin=new Thickness(18)};var agreements=Field(p,"一致意见（每行一条，可留空）","",3);var disagreements=Field(p,"仍存分歧（不强行统一）","",3);var unresolved=Field(p,"未解决问题","",3);var evidence=Field(p,"证据来源","",3);Accept(d,p,"保存审查记录（不构成实施授权）");d.Content=new ScrollViewer(){Content=p};if(d.ShowDialog()==true){Func<string,string[]> lines=t=>t.Split('\n').Where(x=>!String.IsNullOrWhiteSpace(x)).ToArray();await Post("review-record","itemId",i.Id,"agreements",lines(agreements.Text),"disagreements",lines(disagreements.Text),"unresolved",lines(unresolved.Text),"evidence",lines(evidence.Text));await RefreshWorkspace();}}
  async Task Observation(){var m=SelectedMessage();if(m.Author=="user")throw new Exception("请选择Agent消息。");var d=Dialog("差异观察 · 不评分，不推断意识",620,430);var p=new StackPanel(){Margin=new Thickness(18)};var dimension=new ComboBox(){ItemsSource=new string[]{"analysis","judgment","risk_preference","technical_choice","expression","challenge_revision","initiative"},SelectedIndex=0};p.Children.Add(dimension);var note=Field(p,"观察说明（原始回复保持不变）","",6);Accept(d,p,"记录观察");d.Content=p;if(d.ShowDialog()==true){await Post("observe","messageId",m.Id,"dimension",dimension.SelectedItem,"note",note.Text);await RefreshWorkspace();}}
  public WorkbenchApp(string[] args){Root=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..",".."));Config=Path.Combine(Root,"data","workbench-config.json");for(int i=0;i<args.Length-1;i++){if(args[i]=="--config")Config=args[++i];else if(args[i]=="--hybrid-self-test")HybridSelfTest=args[++i];else if(args[i]=="--relay-self-test")RelaySelfTest=args[++i];else if(args[i]=="--self-test")SelfTest=args[++i];else if(args[i]=="--export-preview")Export=args[++i];else if(args[i]=="--project-id")InitialProject=args[++i];else if(args[i]=="--workspace-id")InitialWorkspace=args[++i];else if(args[i]=="--draft-profile")DraftProfile=args[++i];else if(args[i]=="--draft-probe")DraftProbe=args[++i];else if(args[i]=="--view")OpenMaterials=args[++i]=="materials";else if(args[i]=="--materials-test-source")MaterialsTestSource=args[++i];else if(args[i]=="--window-probe")WindowProbe=args[++i];else if(args[i]=="--soak-probe")SoakProof=args[++i];else if(args[i]=="--soak-alt-project")SoakAltProject=args[++i];else if(args[i]=="--soak-alt-workspace")SoakAltWorkspace=args[++i];}CollabMode=Path.GetFileNameWithoutExtension(System.Diagnostics.Process.GetCurrentProcess().MainModule.FileName).EndsWith(".UX.Collab",StringComparison.OrdinalIgnoreCase);UxMode=CollabMode||Path.GetFileNameWithoutExtension(System.Diagnostics.Process.GetCurrentProcess().MainModule.FileName).EndsWith(".UX",StringComparison.OrdinalIgnoreCase)||Path.GetFileNameWithoutExtension(System.Diagnostics.Process.GetCurrentProcess().MainModule.FileName).EndsWith(".UX.Theme",StringComparison.OrdinalIgnoreCase)||args.Contains("--ux");ReadRelayMode();ReadHybridMode();Client=new BridgeClient(Config);using(var xml=XmlReader.Create(Path.Combine(Root,"desktop",UxMode?"UxWindow.xaml":"OfflineWindow.xaml")))Win=(Window)XamlReader.Load(xml);MainWindow=Win;ShutdownMode=ShutdownMode.OnMainWindowClose;Setup();SetupDraftStore();SetupUx();SetupRelayPresentation();SetupHybridPresentation();SetupUxTheme();}
  [STAThread]public static int Main(string[] args){try{var app=new WorkbenchApp(args);int exit=app.Run(app.Win);return Environment.ExitCode!=0?Environment.ExitCode:exit;}catch(Exception e){string root=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..",".."));File.WriteAllText(Path.Combine(root,"data","desktop-startup-error.txt"),e.ToString());if(!args.Contains("--self-test"))MessageBox.Show("桌面启动失败："+e.Message+"\n请先启动D盘工作台后台。");return 1;}}
 }
